    case cudaErrorCompatNotSupportedOnDevice: return CUDA_ERROR_COMPAT_NOT_SUPPORTED_ON_DEVICE;
    case cudaErrorMpsConnectionFailed: return CUDA_ERROR_MPS_CONNECTION_FAILED;
